// MS2-FUNCTIONAL: same calls/bindings; register allocation differs by one byte of length
// @0x142756620
bool SoftParticlesMaterial::HandlePreLightTextureApplication(Context& kContext, NiStandardPixelProgramDescriptor* pkPixDesc,
    Res*& pkWorldPos, Res*& pkWorldNormal, Res*& pkWorldBinormal, Res*& pkWorldTangent, Res*& pkWorldView,
    Res*& pkTangentView, Res*& pkDiffuse, Res*& pkSpecular, Res*& pkSpecPower, Res*& pkGloss, Res*& pkAmbient,
    Res*& pkEmissive, Res*& pkOpacityAccum, Res*& pkAmbientLight, Res*& pkDiffuseLight, Res*& pkSpecularLight,
    Res*& pkDiffuseTex, Res*& pkSpecularTex, unsigned int& uiTexturesApplied, Res** apkUVSets,
    unsigned int uiNumStandardUVs, unsigned int uiNumTexEffectUVs) {
    if (!NiStandardMaterial::HandlePreLightTextureApplication(kContext, pkPixDesc, pkWorldPos, pkWorldNormal,
        pkWorldBinormal, pkWorldTangent, pkWorldView, pkTangentView, pkDiffuse, pkSpecular, pkSpecPower, pkGloss,
        pkAmbient, pkEmissive, pkOpacityAccum, pkAmbientLight, pkDiffuseLight, pkSpecularLight, pkDiffuseTex,
        pkSpecularTex, uiTexturesApplied, apkUVSets, uiNumStandardUVs, uiNumTexEffectUVs))
    {
        return false;
    }

    NiMaterialNode* pkNode = GetAttachableNodeFromLibrary("GetParticleOpacity");
    kContext.m_spConfigurator->AddNode(pkNode);

    unsigned int uiOccurance = 0;
    NiMaterialResource* pkScreenPos = kContext.m_spInputs->AddOutputResource("float3", "TexCoord", "World",
        "ScreenPosPassThrough");
    kContext.m_spConfigurator->AddBinding(pkScreenPos, pkNode->GetInputResourceByVariableName("ScreenPosition"));

    // the scene depth is bound as custom map 00
    NiFixedString kSamplerName;
    if (!GetTextureNameFromTextureEnum(MAP_CUSTOM00, kSamplerName, uiOccurance))
        return false;

    NiMaterialResource* pkSampler = InsertTextureSampler(kContext, kSamplerName, TEXTURE_SAMPLER_2D, uiOccurance);
    kContext.m_spConfigurator->AddBinding(pkSampler, pkNode->GetInputResourceByVariableName("DepthTexture"));
    kContext.m_spConfigurator->AddBinding(
        AddOutputAttribute(kContext.m_spUniforms, "SoftDepth", NiShaderAttributeDesc::ATTRIB_TYPE_FLOAT),
        pkNode->GetInputResourceByVariableName("ParticleDepth"));

    return MultiplyVector(kContext, pkOpacityAccum, pkNode->GetOutputResourceByVariableName("Opacity"),
        pkOpacityAccum);
}
MS2_REPLACE_METHOD(0x142756620, SoftParticlesMaterial, HandlePreLightTextureApplication, 941, 0x31BD09AB);

