// @0x1427569d0
bool SoftParticlesMaterial::HandleViewProjectionFragment(Context& kContext, bool bForceViewPos,
    NiMaterialResource* pkVertWorldPos, NiMaterialResource*& pkVertOutProjectedPos,
    NiMaterialResource*& pkVertOutViewPos)
{
    // always outputs the view position (GetScreenPosition needs its depth)
    if (!NiStandardMaterial::HandleViewProjectionFragment(kContext, true, pkVertWorldPos, pkVertOutProjectedPos,
            pkVertOutViewPos))
        return false;
    return true;
}
